function result = fitCenterCoordinateISMWaterAirInterface(stackInput, varargin)
%FITCENTERCOORDINATEISMWATERAIRINTERFACE 1.2 NA water-objective center ISM fit.
%
%   result = fitCenterCoordinateISMWaterAirInterface()
%   result = fitCenterCoordinateISMWaterAirInterface(stackInput)
%
%   Convenience wrapper for the 2026-05-15 ISM_Aberation_72 test stack:
%
%       D:\Luminosa\Data\PSF_batch_outputs\ISM_Aberation_72\xz_yz_plots\
%       test_20260515_144001_frame_alignment.csv
%
%   Defaults:
%       60x 1.2 NA water objective
%       water/glass/air interface model
%       single-plane center-coordinate fit only
%       raw PTU frames reread frame-by-frame
%       no extra inter-plane shifts or recentering
%       saved shifts ignored unless explicitly enabled and >= 4 px
%       fixed regular PDA23 honeycomb detector geometry
%       no fitted lateral offset and no fitted Zernike defocus
%       100 nm bead diameter modeled as a finite air-side sphere

    if nargin < 1 || isempty(stackInput)
        stackInput = ['D:\Luminosa\Data\PSF_batch_outputs\ISM_Aberation_72\' ...
            'xz_yz_plots\test_20260515_144001_frame_alignment.csv'];
    end

    args = defaultArgs();
    args = overrideArgs(args, varargin{:});
    result = fitCenterCoordinateISMOilAirInterface(stackInput, args{:});
end

function args = defaultArgs()
    root = fileparts(fileparts(mfilename('fullpath')));
    outDir = fullfile(root, 'output_matlab', ...
        'water_air_center_coordinate_ism', 'test_20260515_144001');

    args = { ...
        'useMultiPlane', false, ...
        'objectiveNA', 1.2, ...
        'objectiveMagnification', 60, ...
        'immersionRefractiveIndex', 1.33, ...
        'glassRefractiveIndex', 1.518, ...
        'sampleRefractiveIndex', 1.0003, ...
        'interfaceRadialWeightMode', 'sampleSolidAngle', ...
        'diffractionModel', 'vectorial', ...
        'vectorialPolarizationMode', 'xyAverage', ...
        'excitationPolarizationMode', 'x', ...
        'collectionPolarizationMode', 'xyAverage', ...
        'airInterfaceStageMedium', 'immersion', ...
        'designGlassRefractiveIndex', 1.518, ...
        'coverslipThicknessUm', 190, ...
        'designCoverslipThicknessUm', 190, ...
        'beadDiameterUm', 0.10, ...
        'airBeadAxialSamples', 7, ...
        'beadSubsamples', [5 5 5], ...
        'reuseCache', false, ...
        'useInterPlaneAlignment', false, ...
        'applySavedAlignment', false, ...
        'alignmentShiftMinPx', 4, ...
        'recenterMeasuredVolume', false, ...
        'estimateDetectorLayout', false, ...
        'detectorXYUm', [], ...
        'fitXY', false, ...
        'fitModes', {'astig_x','astig_y','coma_x','coma_y','spherical'}, ...
        'fitDetectorPitchScale', false, ...
        'outputPrefix', 'water_air_center_coordinate', ...
        'reportTitle', 'Water/glass/air center-coordinate ISM fit', ...
        'outputDir', outDir};
end

function args = overrideArgs(args, varargin)
    if mod(numel(varargin), 2) ~= 0
        error('fitCenterCoordinateISMWaterAirInterface:BadNameValue', ...
            'Optional arguments must be Name/Value pairs.');
    end
    for k = 1:2:numel(varargin)
        name = varargin{k};
        idx = find(strcmpi(args(1:2:end), name), 1, 'first');
        if isempty(idx)
            args = [args varargin(k:k+1)]; %#ok<AGROW>
        else
            args{2*idx} = varargin{k+1};
        end
    end
end
